import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
assert.ok(process.env.LINKEDIN_ACCESS_TOKEN);
const response = await fetch('https://api.linkedin.com/rest/organizationAcls?q=roleAssignee', { headers: { Authorization: `Bearer ${process.env.LINKEDIN_ACCESS_TOKEN}`, 'Linkedin-Version': '202609', 'X-Restli-Protocol-Version': '2.0.0' } });
assert.equal(response.status, 200);
const result = await response.json();
assert.ok(Array.isArray(result.elements));
assert.equal(typeof result.paging.start, 'number');
const roles = result.elements;
if (process.argv[2] === 'readback') assert.deepEqual(roles, JSON.parse(readFileSync('roles.json', 'utf8')));
else writeFileSync('roles.json', JSON.stringify(roles), { mode: 0o600 });
console.log(JSON.stringify({ roles: roles.length, retained: process.argv[2] === 'readback' }));
